def transform(grid):
    pattern = [row[10:14] for row in grid[6:11]]
    out = []
    for r in range(11):
        row = []
        for c in range(14):
            if r == 5 or c in (4, 9):
                row.append(3)
            else:
                rr = r if r < 5 else r - 6
                cc = c if c < 4 else (c - 5 if c < 9 else c - 10)
                row.append(pattern[rr][cc])
        out.append(row)
    return out
